function update(){current=null;sync();form.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));try{let x=read();if(key==='supports'&&x.supportBasis==='preliminary'){const v=R.preliminary(x);for(const [k,value] of Object.entries({I:v.I,Z:v.Z,E:v.E,beamMass:v.mass,rodAllow:v.rodAllow,beamAllow:v.beamAllow,rodGrade:L('Cấp 4.6 · giả thiết fy=240 MPa','Class 4.6 · assumed fy=240 MPa'),beamProfile:v.name+L(' · h đặt đứng · giả thiết S235',' · h vertical · assumed S235'),source:L('Tính sơ bộ: hình học hộp lý tưởng, fy ty 240 MPa / thanh 235 MPa; hệ số chia ','Preliminary: ideal RHS geometry, rod fy 240 MPa / bearer fy 235 MPa; divisor ')+x.safety}))$('t-'+k).value=typeof value==='number'?Number(value.toFixed(6)):value;x=read();}for(const f of fields){const e=$('t-'+f.key);if(f.options&&!f.options.some(o=>o[0]===e.value))throw Error('input:'+f.key);if(!e.disabled&&!f.text&&!e.validity.valid||!e.disabled&&!f.options&&!f.text&&e.value.trim()==='')throw Error('input:'+f.key);}const r=E[key](x);current={x,r};$('tool-result').innerHTML=output(x,r);$('tool-error').hidden=true;$('dw-preview').disabled=false;$('dw-print').disabled=false;
 if(key==='fabrication'){$('dw-links').innerHTML=`<a class="calc-link" href="/${en?'en/duct-supports':'vi/gia-do-ong-gio'}/?${new URLSearchParams({shape:x.shape,material:x.material,a:x.a,b:x.b,t:x.t,insulation:x.insulation,insDensity:x.insDensity,extraMass:x.extraMass,runLength:x.length,jointMass:Math.max(0,(r.bodyMass-r.metalMass*x.length+r.jointMass+r.stiffenerMass)/x.length)})}">${L('Tính giá đỡ cho quy cách này','Check supports for this construction')} →</a>`;}
 }catch(e){$('tool-error').hidden=false;$('tool-error').textContent=e.message==='span'?L('Nhịp giữa hai ty phải đủ chứa bề rộng ngoài sau cách nhiệt.','Rod span must accommodate the outside insulated duct width.'):L('Kiểm tra thông số và phạm vi ô nhập.','Check input values and allowed ranges.');const target=e.message==='span'?$('t-span'):e.message.startsWith('input:')?$('t-'+e.message.slice(6)):null;if(target){target.setAttribute('aria-invalid','true');let group=target.closest('details');while(group){group.open=true;group=group.parentElement.closest('details');}}$('tool-result').innerHTML='';$('dw-links').innerHTML='';$('dw-preview').disabled=true;$('dw-print').disabled=true;}}
form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',update);form.addEventListener('change',update);$('dw-reset').onclick=()=>{form.reset();update();};
function report(){update();if(!current)return null;$('engineering-report')?.remove();const a=document.createElement('article');a.id='engineering-report';a.innerHTML='<h1>'+esc(D.title[l])+'</h1>'+output(current.x,current.r,true)+'<h2>'+L('Thông số đầu vào','Inputs')+'</h2>'+table(fields.filter(f=>!$('t-'+f.key).disabled||f.key==='joint').map(f=>[f.label[l],(f.options?$('t-'+f.key).selectedOptions[0]?.textContent:$('t-'+f.key).value)+' '+(f.unit||'')]))+document.querySelector('.calc-method').innerHTML;document.body.append(a);return a;}
$('dw-preview').onclick=()=>{const a=report();if(!a)return;$('report-dialog')?.remove();const d=document.createElement('dialog');d.id='report-dialog';d.innerHTML='<div class="report-dialog-actions"><button type="button" class="text-button" data-close>'+L('Đóng báo cáo','Close report')+'</button></div>'+a.innerHTML;d.setAttribute('aria-label',L('Báo cáo tính toán','Calculation report'));document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.showModal();};$('dw-print').onclick=()=>{if(report())window.HVACPrint.run('engineering');};
document.addEventListener('hvac-project-capture',e=>{e.detail.calculation=current;});document.addEventListener('hvac-project-restore',e=>{if(key==='supports'&&!e.detail?.calculation?.x?.supportBasis)$('t-supportBasis').value='manual';update();});document.addEventListener('hvac-project-transfer',e=>{convertInside(new URLSearchParams(e.detail||{}));update();});
const params=new URLSearchParams(location.search);for(const f of fields){if(!params.has(f.key)||f.text)continue;const e=$('t-'+f.key),v=params.get(f.key);if(f.options?f.options.some(o=>o[0]===v):Number.isFinite(Number(v))&&Number(v)>=f.min&&Number(v)<=f.max)e.value=f.key==='jointMass'?Number(Number(v).toFixed(6)):v;}
function convertInside(params,announce=false){if(!params.has('insideA'))return;const a=Number(params.get('insideA')),b=Number(params.get('insideB')),t=Number($('t-t').value);if(Number.isFinite(a)&&a>=50&&a+2*t<=5000&&($('t-shape').value==='round'||Number.isFinite(b)&&b>=50&&b+2*t<=5000)){$('t-a').value=a+2*t;if($('t-shape').value==='rect')$('t-b').value=b+2*t;if(announce){const note=document.createElement('p');note.className='calc-note';note.textContent=L('Đã nhận kích thước lọt lòng từ chọn ống gió và cộng 2t để thành kích thước ngoài. Vật liệu và chiều dày chưa được chuyển. Đây là quy đổi tại lúc nhận; khi đổi chiều dày hoặc có lớp lót trong, kiểm tra lại kích thước theo bản vẽ.','Received clear internal dimensions from duct sizing and added 2t to obtain outside dimensions. Material and thickness are not transferred. This conversion is made at transfer time; recheck dimensions if thickness changes or internal lining is present.');form.prepend(note);}}}
